{
  "tools": [
    {
      "name": "asset_search",
      "title": "Asset Search",
      "toolset": "asset",
      "description": "Search the asset system by keywords and type. An empty query lists every asset, so use limit and offset to page through. Returns relative asset paths - pass one to asset_info, asset_compile, asset_read or asset_dependencies.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Space separated keywords. Every keyword must match the asset's path or one of its tags. Empty matches everything."
          },
          "type": {
            "type": "string",
            "description": "Filter to one asset type - a file extension (vmdl, vmat, prefab) or friendly name (Model, Material). See asset_types."
          },
          "projectOnly": {
            "type": "boolean",
            "description": "Only assets belonging to the currently open project, excluding engine content and cloud downloads.",
            "default": false
          },
          "unreferencedOnly": {
            "type": "boolean",
            "description": "Only assets nothing else references - useful for finding unused assets. Note map files and code can use an asset without the asset system knowing.",
            "default": false
          },
          "compileFailedOnly": {
            "type": "boolean",
            "description": "Only assets whose last compile failed.",
            "default": false
          },
          "uncompiledOnly": {
            "type": "boolean",
            "description": "Only assets with no compiled version at all.",
            "default": false
          },
          "limit": {
            "type": "integer",
            "description": "How many results to return.",
            "minimum": 1,
            "maximum": 500,
            "default": 50
          },
          "offset": {
            "type": "integer",
            "description": "How many results to skip, for paging.",
            "default": 0
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Total": {
            "type": "integer",
            "description": "How many assets matched in total, beyond this page."
          },
          "Showing": {
            "type": "integer"
          },
          "Offset": {
            "type": "integer"
          },
          "Assets": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Path": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "find_packages",
      "title": "Find Packages",
      "toolset": "package",
      "description": "Search the backend for published packages - models, gamemodes, maps, addons. Plain words search text, and the query supports filters like 'type:model', 'type:gamemode', 'tag:fun' and 'sort:popular' mixed in with the search words.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Search query, e.g. 'barrel type:model sort:popular'."
          },
          "limit": {
            "type": "integer",
            "description": "How many results to return.",
            "minimum": 1,
            "maximum": 100,
            "default": 20
          },
          "offset": {
            "type": "integer",
            "description": "How many results to skip, for paging.",
            "default": 0
          }
        },
        "required": [
          "query"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "TotalCount": {
            "type": "integer",
            "description": "How many packages matched in total, beyond this page."
          },
          "Packages": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Ident": {
                  "type": "string",
                  "description": "The ident get_package and install_package take."
                },
                "Title": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                },
                "Org": {
                  "type": "string"
                },
                "Summary": {
                  "type": "string"
                },
                "Tags": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                },
                "VotesUp": {
                  "type": "integer"
                },
                "Updated": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_entity_classes",
      "title": "Entity Classes",
      "toolset": "hammer",
      "description": "The entity classes that can be placed with hammer_create_entity. Search by name, title or category to list matches; give an exact class name to get its full documentation - every keyvalue with type, default and description, plus inputs and outputs.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Case insensitive substring of the class name, title, category or description. Empty lists every class."
          },
          "name": {
            "type": "string",
            "description": "An exact class name like 'light_spot' to document fully."
          },
          "limit": {
            "type": "integer",
            "description": "How many classes to list.",
            "minimum": 1,
            "maximum": 500,
            "default": 100
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "hammer_find_nodes",
      "title": "Find Nodes",
      "toolset": "hammer",
      "description": "Search the open map's nodes. All filters are optional and combine; with 'near' the results come back nearest first. Each result has the node id the other hammer_ tools take, its kind (Entity, Mesh, GameObject, Group, Instance, Path, Overlay...), name, entity class, position and Hammer's one line description. Nodes inside prefabs aren't included.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "kind": {
            "type": "string",
            "description": "Only this kind of node - Entity, Mesh, GameObject, Group, Instance, Path, PathNode or Overlay. Case insensitive."
          },
          "query": {
            "type": "string",
            "description": "Case insensitive substring of the node's name, entity class, game object name or description."
          },
          "className": {
            "type": "string",
            "description": "Case insensitive substring of the entity class, e.g. 'light' for every light entity."
          },
          "near": {
            "type": "string",
            "description": "Only nodes within 'radius' of this point, as 'x,y,z'. Sorts results nearest first."
          },
          "radius": {
            "type": "number",
            "description": "Search radius around 'near', in units.",
            "default": 512
          },
          "selectedOnly": {
            "type": "boolean",
            "description": "Only nodes that are currently selected.",
            "default": false
          },
          "limit": {
            "type": "integer",
            "description": "How many results to return.",
            "minimum": 1,
            "maximum": 500,
            "default": 100
          },
          "offset": {
            "type": "integer",
            "description": "How many matching results to skip, for paging.",
            "minimum": 0,
            "maximum": 2.1474836E+09,
            "default": 0
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Total": {
            "type": "integer"
          },
          "Nodes": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "integer"
                },
                "Kind": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "ClassName": {
                  "type": "string"
                },
                "Description": {
                  "type": "string"
                },
                "Position": {
                  "type": "string"
                },
                "Parent": {
                  "type": "integer"
                },
                "GameObject": {
                  "type": "string"
                },
                "Selected": {
                  "type": "boolean"
                },
                "Visible": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_list_commands",
      "title": "List Commands",
      "toolset": "hammer",
      "description": "Hammer's named commands - everything its key bindings and menus can do, like GroupSelection, HideUnselected, SelectSimilar, MirrorHorizontal, SnapToGrid, CreatePrefabFromSelection, FrameAllViews or BuildMap. Run one with hammer_run_command.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Case insensitive substring to filter by, e.g. 'select' or 'prefab'. Empty lists all."
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "search_tools",
      "title": "Search Tools",
      "toolset": "instance",
      "description": "Search the live tool registry. Tools live in editor and addon code and come and go as code hotloads, so the tool list from when you connected can be stale - this one never is. Every keyword must match the name, description or parameters; empty returns every tool. Invoke anything you find with call_tool.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Space separated keywords. Empty for every tool."
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    }
  ],
  "total": 128
}
